 "content": "def transform(grid):
    # Identify a full separator row or column between two panels.
    sep_row = next((r for r, row in enumerate(grid) if len(set(row)) == 1), None)
    if sep_row is not None:
        top, bottom = grid[:sep_row], grid[sep_row + 1:]
        top_counts = {}
        bottom_counts = {}
        for row in top:
            for v in row:
                top_counts[v] = top_counts.get(v, 0) + 1
        for row in bottom:
            for v in row:
                bottom_counts[v] = bottom_counts.get(v, 0) + 1
        top_bg = max(top_counts, key=top_counts.get)
        top_fg = next(v for row in top for v in row if v != top_bg)
        bottom_bg = max(bottom_counts, key=bottom_counts.get)
        return [[3 if v == top_fg else bottom_bg for v in row] for row in top]

    sep_col = next(c for c in range(len(grid[0])) if all(row[c] == grid[0][c] for row in grid))
    left = [row[:sep_col] for row in grid]
    right = [row[sep_col + 1:] for row in grid]

    def bg_fg(panel):
        counts = {}
        for row in panel:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        bg = max(counts, key=counts.get)
        fg = next(v for row in panel for v in row if v != bg)
        return bg, fg

    _, left_fg = bg_fg(left)
    _, right_fg = bg_fg(right)
    width = min(len(left[0]), len(right[0]))
    return [[3 if left[r][c] == left_fg and right[r][c] == right_fg else right_fg
             for c in range(width)] for r in range(len(grid))]

